/// Marker type for the client side of `M_ObjectManager`.
#[derive(Debug, Clone, Copy)]
pub enum ClientRole {}

impl crate::Role for ClientRole {
    type Incoming = ClientMessage;
    type Outgoing = ServiceMessage;
    const NAME: &'static str = "M_ObjectManager::Client";

    fn vtable() -> &'static onboardapi_sys::obapi_vtable {
        // SAFETY: the vtable is an immutable static defined by the C++ shim.
        unsafe { &*(&raw const onboardapi_sys::obapi_ObjectManager_client_vtable) }
    }
}

impl crate::ClientSide for ClientRole {}

/// `M_ObjectManager::Client`: receives [`ClientMessage`], sends [`ServiceMessage`].
pub type Client = crate::Endpoint<ClientRole>;

/// Typed senders, one per outgoing operation. They encode straight from borrowed data.
impl crate::Endpoint<ClientRole> {
    /// Request for the service to transform a position from one coordinate frame to another.
    pub fn request_position(&self, pos_id: &str, source_position: &crate::common::PositionType, target_coordinate_frame: &str) -> crate::Result<()> {
        let mut w = Writer::default();
        pos_id.encode(&mut w);
        source_position.encode(&mut w);
        target_coordinate_frame.encode(&mut w);
        self.send_raw(0, w.as_bytes())
    }

    /// Cmd to add or replace an existing point object.
    /// Note: If the object with the same ID already exists it will be replaced.
    pub fn cmd_add_update_point(&self, key_id: &str, obj: &PointObjectType) -> crate::Result<()> {
        let mut w = Writer::default();
        key_id.encode(&mut w);
        obj.encode(&mut w);
        self.send_raw(1, w.as_bytes())
    }

    /// Cmd to modify an existing point object.
    /// Note: This command can only be used to modify an already existing object.
    pub fn cmd_modify_point(&self, key_id: &str, obj: &ModifyPointType) -> crate::Result<()> {
        let mut w = Writer::default();
        key_id.encode(&mut w);
        obj.encode(&mut w);
        self.send_raw(2, w.as_bytes())
    }

    /// Cmd to add or replace an existing multi-point object.
    /// Note: If the object with the same ID already exists it will be replaced.
    pub fn cmd_add_update_multi_point(&self, key_id: &str, obj: &MultiPointObjectType) -> crate::Result<()> {
        let mut w = Writer::default();
        key_id.encode(&mut w);
        obj.encode(&mut w);
        self.send_raw(3, w.as_bytes())
    }

    /// Cmd to modify an existing multi-point object.
    /// Note: This command can only be used to modify an already existing object.
    pub fn cmd_modify_multi_point(&self, key_id: &str, obj: &ModifyMultiPointType) -> crate::Result<()> {
        let mut w = Writer::default();
        key_id.encode(&mut w);
        obj.encode(&mut w);
        self.send_raw(4, w.as_bytes())
    }

    /// Cmd to remove an existing object.
    /// Note: This can be used to remove a relative point, sector or polygon object.
    pub fn cmd_remove(&self, key_id: &str) -> crate::Result<()> {
        let mut w = Writer::default();
        key_id.encode(&mut w);
        self.send_raw(5, w.as_bytes())
    }

}

